{
  "findings": [
    {
      "check_id": "CKV_AWS_17",
      "title": "RDS instance is publicly accessible",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "CRITICAL",
      "explanation": "The RDS instance is configured to be publicly accessible, which exposes the database to the internet. This increases the risk of unauthorized access and data breaches."
    },
    {
      "check_id": "CKV_AWS_16",
      "title": "RDS instance does not enable Multi-AZ deployment",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "HIGH",
      "explanation": "Multi-AZ deployment is not enabled, which reduces the availability and fault tolerance of the database in case of an outage in one availability zone."
    },
    {
      "check_id": "CKV_AWS_14",
      "title": "RDS instance does not use storage encryption",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "HIGH",
      "explanation": "The RDS instance does not have storage encryption enabled, which could lead to sensitive data being stored in plaintext and accessible if the storage is compromised."
    }
  ],
  "patched_code": "resource \"aws_db_instance\" \"levelup-rds\" {\n  identifier = \"${var.ENVIRONMENT}-levelup-rds\"\n  allocated_storage = var.LEVELUP_RDS_ALLOCATED_STORAGE\n  storage_type = \"gp2\"\n  engine = var.LEVELUP_RDS_ENGINE\n  engine_version = var.LEVELUP_RDS_ENGINE_VERSION\n  instance_class = var.DB_INSTANCE_CLASS\n  backup_retention_period = var.BACKUP_RETENTION_PERIOD\n  publicly_accessible = false\n  username = var.LEVELUP_RDS_USERNAME\n  password = var.LEVELUP_RDS_PASSWORD\n  vpc_security_group_ids = [aws_security_group.levelup-rds-sg.id]\n  db_subnet_group_name = aws_db_subnet_group.levelup-rds-subnet-group.name\n  multi_az = true\n  storage_encrypted = true\n}",
  "fix_summary": "Set `publicly_accessible` to `false` to prevent public exposure of the RDS instance. Enabled `multi_az` for high availability and fault tolerance. Added `storage_encrypted = true` to ensure data at rest is encrypted."
}
